#!/usr/bin/env python3
import sys
import math
def is_int_distance_yz(y, z):
    dist = 0
    for (yi, zi) in zip(y, z):
        dist += (yi - zi)**2
    dist_sqrt = int(math.sqrt(dist))
    return dist == dist_sqrt**2

def solve(N: int, D: int, X: "List[List[int]]"):
    ans = 0
    for i in range(N-1):
        for j in range(i+1, N):
            if is_int_distance_yz(y=X[i], z=X[j]):
                ans += 1
    print(ans)


# Generated by 1.1.6 https://github.com/kyuridenamida/atcoder-tools  (tips: You use the default template now. You can remove this line by using your custom template)
def main():
    def iterate_tokens():
        for line in sys.stdin:
            for word in line.split():
                yield word
    tokens = iterate_tokens()
    N = int(next(tokens))  # type: int
    D = int(next(tokens))  # type: int
    X = [[int(next(tokens)) for _ in range(D)] for _ in range(N)]  # type: "List[List[int]]"
    solve(N, D, X)

if __name__ == '__main__':
    main()
